import { getAccessToken } from "@kinde-oss/kinde-auth-react";
import { has } from "@kinde-oss/kinde-auth-react/utils";

export function DeleteButton() {
  const allowed = has({ permissions: ["delete:todos"] });
  const { getAccessToken } = useKindeAuth();

  async function removeTodo() {
    const token = await getAccessToken();
    await fetch("/api/todos/1", {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });
  }

  return allowed ? <button onClick={removeTodo}>Delete</button> : null;
}

